using System.Net.Http.Json;using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganizerController(ApiClient api):BaseController
{
 public async Task<IActionResult> Dashboard(){var g=Require("Organizer");if(g!=null)return g;var id=int.TryParse(HttpContext.Session.GetString("UserId"),out var uid)?uid:0;var all=await api.Get<List<EventVm>>("api/events")??[];var mine=all.Where(e=>e.OrganizerId==id).OrderBy(e=>e.EventDate).ToList();var counts=new Dictionary<int,int>();foreach(var e in mine){var rows=await api.Get<List<EnrolmentVm>>($"api/events/{e.EventId}/enrolments");counts[e.EventId]=rows?.Count(x=>x.Status=="Active")??0;}ViewBag.Counts=counts;return View(mine);}
 public IActionResult Create(){var g=Require("Organizer");return g??View(new EventVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(EventVm vm,IFormFile? banner){var g=Require("Organizer");if(g!=null)return g;if(!ModelState.IsValid)return View(vm);var res=await api.Send(HttpMethod.Post,"api/events",Payload(vm));if(!res.IsSuccessStatusCode){ModelState.AddModelError("","Could not create event. Verify all fields and API availability.");return View(vm);}var created=await res.Content.ReadFromJsonAsync<EventVm>();if(banner is {Length:>0}&&created!=null){var up=await api.Upload($"api/files/events/{created.EventId}/banner",banner);if(!up.IsSuccessStatusCode)TempData["Message"]="Event created, but banner upload failed.";}TempData["Message"]="Event created successfully.";return RedirectToAction(nameof(Dashboard));}
 public async Task<IActionResult> Edit(int id){var g=Require("Organizer");if(g!=null)return g;var e=await api.Get<EventVm>($"api/events/{id}");if(e==null)return NotFound();if(e.OrganizerId!=CurrentOrganizerId())return Forbid();return View(e);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,EventVm vm,IFormFile? banner){var g=Require("Organizer");if(g!=null)return g;if(!ModelState.IsValid)return View(vm);var res=await api.Send(HttpMethod.Put,$"api/events/{id}",Payload(vm));if(!res.IsSuccessStatusCode){ModelState.AddModelError("","Update failed. The event may have enrolments or the API rejected the details.");return View(vm);}if(banner is {Length:>0}){var up=await api.Upload($"api/files/events/{id}/banner",banner);if(!up.IsSuccessStatusCode)TempData["Message"]="Event updated, but banner upload failed.";}TempData["Message"]="Event updated.";return RedirectToAction(nameof(Dashboard));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var g=Require("Organizer");if(g!=null)return g;var res=await api.Send(HttpMethod.Delete,$"api/events/{id}");TempData["Message"]=res.IsSuccessStatusCode?"Event deleted.":"Event could not be deleted. Events with enrolments are retained for record integrity.";return RedirectToAction(nameof(Dashboard));}
 public async Task<IActionResult> Categories(int id){var g=Require("Organizer");if(g!=null)return g;ViewBag.EventId=id;ViewBag.Event=await api.Get<EventVm>($"api/events/{id}");if(ViewBag.Event==null)return NotFound();if(((EventVm)ViewBag.Event).OrganizerId!=CurrentOrganizerId())return Forbid();ViewBag.Assigned=await api.Get<List<CategoryVm>>($"api/events/{id}/categories")??[];ViewBag.Categories=await api.Get<List<CategoryVm>>("api/categories")??[];return View(new CategoryVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateCategory(int eventId,CategoryVm vm){var g=Require("Organizer");if(g!=null)return g;if(!ModelState.IsValid||vm.MaxAge<vm.MinAge){TempData["Message"]="Enter a valid category and age range.";return RedirectToAction(nameof(Categories),new{id=eventId});}var create=await api.Send(HttpMethod.Post,"api/categories",new{vm.CategoryName,vm.Description,vm.MinAge,vm.MaxAge,vm.DistanceKm});if(!create.IsSuccessStatusCode){TempData["Message"]="Category could not be created. It may already exist.";return RedirectToAction(nameof(Categories),new{id=eventId});}var c=await create.Content.ReadFromJsonAsync<CategoryVm>();if(c!=null){var assign=await api.Send(HttpMethod.Post,$"api/events/{eventId}/categories/{c.CategoryId}",new{vm.MaxParticipants,vm.EntryFee});TempData["Message"]=assign.IsSuccessStatusCode?"Category created and assigned.":"Category created but could not be assigned to this event.";}return RedirectToAction(nameof(Categories),new{id=eventId});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AssignCategory(int eventId,int categoryId,int maxParticipants,decimal entryFee){var g=Require("Organizer");if(g!=null)return g;var r=await api.Send(HttpMethod.Post,$"api/events/{eventId}/categories/{categoryId}",new{MaxParticipants=maxParticipants,EntryFee=entryFee});TempData["Message"]=r.IsSuccessStatusCode?"Category assigned.":"Could not assign category.";return RedirectToAction(nameof(Categories),new{id=eventId});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RemoveCategory(int eventId,int categoryId){var g=Require("Organizer");if(g!=null)return g;var r=await api.Send(HttpMethod.Delete,$"api/events/{eventId}/categories/{categoryId}");TempData["Message"]=r.IsSuccessStatusCode?"Category removed.":"Category cannot be removed while participants are enrolled.";return RedirectToAction(nameof(Categories),new{id=eventId});}
 public async Task<IActionResult> Enrolments(int id){var g=Require("Organizer");if(g!=null)return g;ViewBag.Event=await api.Get<EventVm>($"api/events/{id}");if(ViewBag.Event==null)return NotFound();if(((EventVm)ViewBag.Event).OrganizerId!=CurrentOrganizerId())return Forbid();var rows=await api.Get<List<EnrolmentVm>>($"api/events/{id}/enrolments")??[];return View(rows);}
 public async Task<IActionResult> Results(int id){var g=Require("Organizer");if(g!=null)return g;ViewBag.Event=await api.Get<EventVm>($"api/events/{id}");if(ViewBag.Event==null)return NotFound();if(((EventVm)ViewBag.Event).OrganizerId!=CurrentOrganizerId())return Forbid();var rows=await api.Get<List<EnrolmentVm>>($"api/events/{id}/enrolments")??[];foreach(var row in rows){var result=await api.Get<ResultVm>($"api/enrolments/{row.EnrolmentId}/result");if(result!=null){row.FinishPosition=result.FinishPosition;row.FinishTime=result.FinishTime;row.ResultStatus=result.ResultStatus;}}return View(rows);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveResult(int id,int enrolmentId,int? finishPosition,TimeSpan? finishTime,string resultStatus){var g=Require("Organizer");if(g!=null)return g;var payload=new{FinishPosition=finishPosition,FinishTime=finishTime,ResultStatus=resultStatus};var check=await api.Get<ResultVm>($"api/enrolments/{enrolmentId}/result");var response=await api.Send(check==null?HttpMethod.Post:HttpMethod.Put,$"api/enrolments/{enrolmentId}/result",payload);TempData["Message"]=response.IsSuccessStatusCode?"Result saved.":"Result could not be saved. Check the position, time and status.";return RedirectToAction(nameof(Results),new{id});}
 private int CurrentOrganizerId()=>int.TryParse(HttpContext.Session.GetString("UserId"),out var id)?id:0;
 private static object Payload(EventVm v)=>new{v.EventName,v.Description,v.EventDate,v.StartTime,v.Venue,v.Location,v.MaxParticipants,v.Status,v.EventType};
}
